606	// assertJSONLines compares actual output lines against expected JSON strings,
607	// using semantic JSON equality (order-independent for object keys).
608	func assertJSONLines(t *testing.T, actual []byte, expected []string) {
609		t.Helper()
610	
611		actualLines := nonEmptyLines(actual)
