621		for i := range expected {
622			var got, want interface{}
623			if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
624				t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
