626			if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
627				t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
628			}
629			if !reflect.DeepEqual(got, want) {
630				prettyGot, _ := json.MarshalIndent(got, "", "  ")   //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
631				prettyWant, _ := json.MarshalIndent(want, "", "  ") //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
632				t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
633			}
634		}
635	}
